let liveController=null,liveRetry=null,clockAnchor={clock:0,received:0,speed:1,paused:true},latestSync=0;
function applyState(snapshot,draw=true){if(snapshot.sync_time&&snapshot.sync_time<latestSync)return;latestSync=snapshot.sync_time||latestSync;state=snapshot;clockAnchor={clock:state.clock,received:performance.now(),speed:state.speed,paused:state.paused};if(draw)render()}
function renderClock(){if(!state)return;const elapsed=clockAnchor.paused?0:Math.min(3,(performance.now()-clockAnchor.received)/1000);$('clock').textContent=time(clockAnchor.clock+elapsed*clockAnchor.speed)}
function stopLive(){clearTimeout(liveRetry);liveController?.abort();liveController=null;latestSync=0}
async function connectLive(){
 stopLive();if(!auth)return;const token=auth,controller=new AbortController();liveController=controller;
 try{
  const response=await fetch('/api/live',{headers:authHeaders(),signal:controller.signal});
  if(response.status===401){auth='';sessionStorage.removeItem('noe-token');showLobby();return}
  if(!response.ok||!response.body)throw Error('Live-Verbindung fehlgeschlagen');
  const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';
  while(!controller.signal.aborted){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let end;
   while((end=buffer.indexOf('\n\n'))>=0){const event=buffer.slice(0,end);buffer=buffer.slice(end+2);const data=event.split('\n').find(line=>line.startsWith('data: '));if(data&&auth===token)applyState(JSON.parse(data.slice(6)))}
  }
 }catch(error){if(!controller.signal.aborted&&auth===token)toast('Live-Verbindung unterbrochen. Verbinde erneut …')}
 finally{if(!controller.signal.aborted&&auth===token)liveRetry=setTimeout(connectLive,1500)}
}
showLobby();if(auth)connectLive();setInterval(renderClock,250);
document.addEventListener('visibilitychange',()=>{if(!document.hidden){renderClock();if(auth&&!liveController)connectLive()}});


