function renderRadio(){
 const calls=(state.radio_calls||[]).filter(c=>c.state!=='closed');
 const markup=items=>items.map(c=>{
  const j=state.jobs.find(j=>j.id===c.job),v=state.vehicles.find(v=>v.id===c.vehicle),other=j?.owner&&j.owner!==state.session.me;
  const label=({calling:'LEO hört',reason_needed:'Verstanden, Grund der Nachforderung?, kommen',awaiting_dispatch:'Nachforderung bestätigen'})[c.state];
  const confirmationReady=['Polizei','Feuerwehr'].includes(c.kind)||j?.vehicles.some(id=>{const unit=state.vehicles.find(v=>v.id===id);return id!==c.vehicle&&unit?.type===c.kind&&unit.job===j.id});
  return `<div class="radio-call"><b>${esc(v?.callsign)} · ${esc(c.state==='calling'?'Funkwunsch':c.kind+' nachgefordert')}</b><span>${c.state==='reason_needed'?'Grund noch offen':c.state==='awaiting_dispatch'?esc(c.reason):'LEO von '+esc(v?.callsign)+', kommen.'}</span><div><button data-radio="${c.id}" data-step="${({calling:'listen',reason_needed:'reason',awaiting_dispatch:'confirm'})[c.state]}" ${other||c.state==='awaiting_dispatch'&&!confirmationReady?'disabled':''}>${esc(label)}</button>${c.state!=='calling'?`<button data-radio="${c.id}" data-step="repeat" ${other?'disabled':''}>Wiederholen, kommen</button><button data-radio="${c.id}" data-step="wait" ${other?'disabled':''}>Warten</button>`:''}<button data-radio-job="${c.job}">Einsatz öffnen</button>${c.state==='awaiting_dispatch'&&!confirmationReady?`<button data-radio="${c.id}" data-step="unavailable" ${other?'disabled':''}>Noch kein Rettungsmittel verfügbar</button>`:''}</div></div>`
 }).join('');
 patchHtml($('radio-queue'),markup(calls));if($('radio-detail'))patchHtml($('radio-detail'),markup(calls.filter(c=>c.job===selected)));
 document.querySelectorAll('[data-radio]').forEach(b=>b.onclick=()=>{const c=calls.find(c=>c.id===b.dataset.radio);command('radio',{job:c.job,call:c.id,step:b.dataset.step})});
 document.querySelectorAll('[data-radio-job]').forEach(b=>b.onclick=()=>openDispatch(b.dataset.radioJob));
}

fetch("/api/addresses").then(r=>r.json()).then(data=>{addressPoints=data.addresses}).catch(()=>toast("Adresskatalog konnte nicht geladen werden."));
